-- T0002
{id="t0002-01",kind="set",pieces={"FirstAidKit","Bandage"},where={{place="hospital",spot="corpse",lean="containment",rival="agricultural",outfit="medical"}},title="The sealed kit on the medical coat",body="The kit's seal is unbroken. A bandage has been folded around its handle, still clean, with a patient wrist label tied through the fold and no name on it."},
{id="t0002-02",kind="set",pieces={"Notebook","WaterBottle"},where={{place="hospital",spot="corpse",lean="agricultural",rival="containment",outfit="medical"}},title="The bottle with a leaf-shaped tide",body="A brown tide line circles the bottle; the notebook beside it has one page stuck to the cap. When it lifts, a pressed leaf outline remains on the paper."},
-- T0003
{id="t0003-01",kind="set",pieces={"DuctTape","GardeningSprayEmpty"},where={{place="farm",spot="furniture",lean="containment",rival="agricultural"}},title="Duct tape with the second residue",body="seed husks cling to the duct tape, while bleach marks the empty garden sprayer. road mud joins the two in one tied bundle."},
{id="t0003-02",kind="set",pieces={"SeedBag","HandShovel"},where={{place="farm",spot="furniture",lean="agricultural",rival="containment"}},title="The seed bag holds a narrow trench",body="The seed bag is folded shut around the shovel handle. A straight line of dark soil runs from the blade to the bag's seam, but the shovel has no soil on its grip."},
-- T0004
{id="t0004-01",kind="set",pieces={"Map","Lunchbox"},where={{place="checkpoint",spot="vehicle",lean="containment",rival="agricultural"}},title="The lunch packed for the closed lane",body="The lunchbox is wedged beneath the map's fold. The route line passes the checkpoint and stops; a spoon has been laid across the road home."},
{id="t0004-02",kind="set",pieces={"Bucket","Fertilizer"},where={{place="checkpoint",spot="vehicle",lean="agricultural",rival="containment"}},title="The powder gathered in the bucket seam",body="Pale granules cling inside the bucket's rim. The fertilizer sack beside it is dry and carefully folded, with its open corner tucked under the seat."},
-- T0005
{id="t0005-01",kind="set",pieces={"Briefcase","Screwdriver"},where={{place="office",spot="furniture",lean="containment",rival="agricultural"}},title="The briefcase with an intact lock",body="The screwdriver lies inside the open briefcase. Its lock is intact, but the metal around the keyhole is bright from repeated turning; a loose key sits in the lining."},
{id="t0005-02",kind="set",pieces={"SeedBag","Fertilizer"},where={{place="office",spot="furniture",lean="agricultural",rival="containment"}},title="The seed packet tucked in the fertilizer fold",body="A seed packet is tucked into the fertilizer sack's stitched fold. Its planting diagram is intact; the small panel for mixing instructions has been cut out cleanly."},
-- T0006
{id="t0006-01",kind="set",pieces={"Map","Postcard"},where={{place="bookstore",spot="mailbox",lean="containment",rival="agricultural"}},title="The postcard addressed to a crossed street",body="The postcard is stamped and addressed, but the map beneath it ends at a street crossed out in pencil. The message stops after, “We were told to wait by—”."},
{id="t0006-02",kind="set",pieces={"Newspaper","Notebook"},where={{place="bookstore",spot="mailbox",lean="agricultural",rival="containment"}},title="The garden column with no matching season",body="A newspaper gardening column is folded around a notebook sketch of three crop rows. The drawing has a water line but no planting date; the column is for winter."},
-- T0007
{id="t0007-01",kind="set",pieces={"Whistle","FirstAidKit"},where={{place="transmission",spot="vehicle",lean="containment",rival="agricultural"}},title="Warning whistle beside the spare mark",body="the warning whistle and first-aid kit were sealed together but never opened. soot darkens the bundle; clean outlines show it was packed before the fire."},
{id="t0007-02",kind="set",pieces={"Notebook","WaterBottle"},where={{place="transmission",spot="vehicle",lean="agricultural",rival="containment"}},title="The rain sketch runs into the bottle ring",body="The notebook shows rain crossing a set of crop rows. A water bottle rests on the open page; its dry ring circles the word “downhill,” written once and then erased."},
-- T0008
{id="t0008-01",kind="set",pieces={"Rope","WaterBottle"},where={{place="warehouse",spot="furniture",lean="containment",rival="agricultural"}},title="Short rope and a scratched-out tag",body="A numbered evacuation tag is knotted to the short rope, its name line scratched out. The water bottle has its label peeled off and the same number inked on the cap. Both are tied with one cord."},
{id="t0008-02",kind="set",pieces={"Bucket","Notebook"},where={{place="warehouse",spot="furniture",lean="agricultural",rival="containment"}},title="The trial strip curled after spraying",body="The notebook rests across the bucket. Its page labels two strips “control — standing” and “trial spray — curled by noon.” The next line reads “mix still active after valve shut.”"},
-- T0009
{id="t0009-01",kind="set",pieces={"Newspaper","RubberBand"},where={{place="government",spot="furniture",lean="containment",rival="agricultural"}},title="The headline held open over its correction",body="A rubber band keeps the newspaper open, but its fold covers the correction column. The headline is still visible; the folded page has split along the correction's first sentence."},
{id="t0009-02",kind="set",pieces={"GardeningSprayEmpty","Notebook"},where={{place="government",spot="furniture",lean="agricultural",rival="containment"}},title="The sprayer left its outline on the page",body="The empty garden sprayer has left a clean circle on the notebook beneath it. A dried green line runs from the nozzle to a sketch of crop rows."},
-- T0010
{id="t0010-01",kind="written",pieces={"idcard"},where={{place="farm",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},person="person-a",title="Temporary field access card",body="Field plots: weekly soil checks. Road access may close at short notice. Reverse: “Keep the old mare in the dry stall tonight.”"},
{id="t0010-02",kind="set",pieces={"Map","HandShovel"},where={{place="farm",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},person="person-a",title="The row sprayed twice",body="The map's crop row is circled twice, with a pencilled note: second pass, same mix. Soil fills the shovel socket and the blade is stained blue-green from the treated rows."},
-- T0011
{id="t0011-01",kind="written",pieces={"idcard"},where={{place="office",spot="mailbox",lean="containment",rival="agricultural"}},person="person-b",title="County message runner card",body="Delivery: office to road crews. Return copy expected when access resumes. Reverse: “Please bring the chipped blue cup back; it was my sister's.”"},
{id="t0011-02",kind="set",pieces={"Twine","HandTorch"},where={{place="office",spot="mailbox",lean="containment",rival="agricultural"}},person="person-b",title="Baling twine with the unclosed tally",body="the baling twine and hand torch smell sharply of bleach. mud outlines between them show that a third object was removed."},
-- T0012
{id="t0012-01",kind="written",pieces={"businesscard"},where={{place="checkpoint",spot="vehicle",lean="containment",rival="agricultural"}},person="person-c",title="Courier card with a late return",body="Transfer window: after road access ends. Return copy to sender. Reverse: “Bread for Mother, no crust if it is still warm.”"},
{id="t0012-02",kind="set",pieces={"Crayons","AnimalFeedBag"},where={{place="checkpoint",spot="vehicle",lean="agricultural",rival="containment"}},person="person-c",title="After on the wax crayons, the first copy",body="yellow fertilizer crystals fill the seam between the wax crayons and animal-feed sack. the crystals are damp beneath a dry outer layer."},
-- T0013
{id="t0013-01",kind="set",pieces={"UmbrellaBlack","Camera"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Black umbrella with the second residue",body="the black umbrella bears a treated-seed stain and the camera a closure mark. one rope knot holds both objects together.",anchor={map="IrvingtonStashMap1",mark=1}},
{id="t0013-02",kind="set",pieces={"Notebook","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The bottle's ring crosses a row sketch",body="A clear ring dries across the notebook's crop-row drawing. The bottle cap is clean; the page beneath it is stained only where the drawn rows meet.",anchor={map="IrvingtonStashMap1",note=1}},
{id="t0013-03",kind="written",pieces={"dispatch"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Dispatch copy with an unfinished return",body="“Track access ends at the barrier. Keep the west lane clear for the last vehicle.” The receiving line is blank; on the back, someone asks for a green scarf to be saved.\n\nThe person who handed this to me asked me to keep the date. I did, though the next version left that day out entirely.\n\nThe next morning I looked for a second copy and found only the envelope. I left this one unfolded for whoever came after us.",anchor={map="IrvingtonStashMap1",note=2}},
{id="t0013-04",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The row count continues past the page",body="The note lists three crop rows and a water check, then continues onto the cover. “Bring the small boots home” is written below the last line.\n\nI carried it home because there was nowhere open to return it. The mark did not come off when I tried to wash my hands.\n\nThe next morning I looked for a second copy and found only the envelope. I left this one unfolded for whoever came after us.",anchor={map="IrvingtonStashMap1",note=3}},
-- T0014
{id="t0014-01",kind="set",pieces={"Screwdriver","RubberBand"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The tire offer marked on a tool handle",body="A rubber band holds a seed-treatment slip to the screwdriver. Beside the wheel sketch, the outer groove is packed with green powder like the dust on treated seed, and the handle smells of it.",anchor={print="AmericanTire"}},
{id="t0014-02",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="The fourth tire omitted from the return",body="The receipt charges four tires to the county road crew, but lists only three serial numbers. Beside the blank fourth line, someone wrote “keep off public return until clearance review.” Reverse: “Save the smoothest for the child's bicycle.”\n\nI asked for the old page back after the new instructions arrived. They said it had been destroyed, but its corner was still in my pocket.\n\nThe person who was supposed to collect it had no time to stop. I did not put it back with the rest of the ordinary papers.",anchor={print="AmericanTire"}},
-- T0015
{id="t0015-01",kind="set",pieces={"Crowbar","Briefcase"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Crowbar beside the spare mark",body="the crowbar and briefcase are wrapped in a child's raincoat. one stayed dry while the other was left in road mud.",anchor={map="EkronStashMap8",mark=1}},
{id="t0015-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The note that asks someone to come back",body="“Forget the box. Just get here before the rows are watered.” The lower half is torn away; a muddy thumb has blurred the place where a name would go.\n\nI had promised to bring this home for supper. Its date and the empty chair at the table now belong to the same evening.\n\nPerhaps the new instructions were meant to help us. They arrived after we had already followed the old ones.",anchor={map="EkronStashMap8",mark=1}},
-- T0016
{id="t0016-01",kind="set",pieces={"PipeWrench","Map"},where={{place="transmission",spot="vehicle",lean="containment",rival="agricultural"}},title="Pipe wrench with the unclosed tally",body="a broken barrier board crushed the pipe wrench against the folded road map. clean undersides show both were there before the road was blocked.",anchor={scene="RVSPlonkies"}},
{id="t0016-02",kind="set",pieces={"SeedBag","Fertilizer"},where={{place="farm",spot="vehicle",lean="agricultural",rival="containment"}},title="The seed sack kept beside the fertilizer",body="The seed sack is wedged against the fertilizer bag in the van. Its stitched mouth is green at one corner; the label on the fertilizer is clean where a thumb would lift it.",anchor={scene="RVSPlonkies"}},
-- T0017
{id="t0017-01",kind="set",pieces={"FirstAidKit","Bandage"},where={{place="police",spot="furniture",lean="containment",rival="agricultural"}},title="The first-aid kit under the kitchen shelf",body="The kit is sealed and pushed behind a rat-chewed board. One bandage has been set on top, dry and neatly folded as if someone expected to return for it.",anchor={scene="RDSRatKing"}},
{id="t0017-02",kind="set",pieces={"GardeningSprayEmpty","Notebook"},where={{place="farm",spot="furniture",lean="agricultural",rival="containment"}},title="The spray bottle with a page stuck to it",body="The empty sprayer is tacky around its trigger. A notebook page has dried against its side; the page shows a rat-chewed root beside three crop rows.",anchor={scene="RDSRatKing"}},
-- T0018
{id="t0018-01",kind="set",pieces={"Wrench","WalkieTalkie1"},where={{place="office",spot="furniture",lean="containment",rival="agricultural"}},title="Open wrench with the unclosed tally",body="three pickup dots mark the open wrench and hand radio. two were scratched away without wear around them.",anchor={scene="RBJackieJaye",version="A"}},
{id="t0018-02",kind="set",pieces={"Notebook","WaterBottle"},where={{place="office",spot="furniture",lean="agricultural",rival="containment"}},title="The field sketch under the studio glass",body="The notebook is trapped beneath a glass desk cover. A crop-row sketch has a water stain across its center; the bottle beside it is dry and capped.",anchor={scene="RBJackieJaye",version="B"}},
-- T0020
{id="t0020-01",kind="set",pieces={"TirePump","FirstAidKit"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Tire pump with the unclosed tally",body="the tire pump is tied to the first-aid kit by a clipped lanyard. an empty loop shows where an identifying tag was cut off.",anchor={map="BBurgStashMap1",mark=1}},
{id="t0020-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Closed windows",body="Please keep the lesson room windows shut until the spray crew has finished the field across the road. The children can smell it from the front room, and the paint on the porch rail has gone dull since the new mix went on the corn.\n\nTheir mother has paid for the whole week already.",anchor={map="BBurgStashMap1",mark=1}},
-- T0021
{id="t0021-01",kind="set",pieces={"Jack","Clipboard"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Car jack beside the spare mark",body="the car jack and clipboard carry the same black paint. a fresh scrape exposes an older evacuation color beneath.",anchor={map="LouisvilleStashMap1",mark=1}},
{id="t0021-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The tin is for screws",body="The test-plot sample jars lost their labels in the rain. Don't put pesticide samples in the rifle-cleaning tin again; the household still keeps its loose screws there.\n\nThe seed-treatment crew left the plot half sprayed and the rows beside it have gone yellow. I scrubbed the tin twice and it still smells sweet.\n\nI stayed until dark in case the crew came back for the jars. No one did.",anchor={map="LouisvilleStashMap1",mark=1}},
-- T0022
{id="t0022-01",kind="set",pieces={"LugWrench","HandTorch"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Lug wrench with the unclosed tally",body="road dust coats the lug wrench and hand torch, but their ties are clean and newly cut. the bundle was repacked after travel.",anchor={map="MarchRidgeStashMap1",mark=1}},
{id="t0022-02",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The jars stay sealed",body="Keep the pesticide trial jars sealed until the spray plot is dry. The neighbor's calves got into the treated rows and have not eaten since; the dog is still in the yard.\n\nI kept one copy for myself. The trial crew promised to come for the other jars and never did.\n\nThe label on the lid is the only part of that week I trusted.",anchor={map="MarchRidgeStashMap1",mark=1}},
-- T0023
{id="t0023-01",kind="set",pieces={"RadioReceiver","Battery","Screwdriver"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Acknowledged from the bench",body="The receiver sat on the repair bench during the evacuation alert, screwdriver beside its charged battery. Dispatch's log says it acknowledged the alert there. The owner signed for it next morning and lost lunch money for the missed shift.",anchor={print="CircuitalHealing"}},
{id="t0023-02",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="No fault at the plot",body="The field trial's receiver came back marked 'no fault found,' though it stopped transmitting at the plot. The owner asked to hold the invoice until after harvest; the bench still wants payment.\n\nThe plot beside it was sprayed twice that week and the rows nearest the receiver wilted first. I wrote the dates here while I could still remember them.\n\nThe bench could not say whether the spray or the receiver failed first.",anchor={print="CircuitalHealing"}},
-- T0024
{id="t0024-01",kind="set",pieces={"SpeedingTicket","BeerBottle","Pencil"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="A citation after closing",body="The speeding citation is stamped after the access lane's closure; the beer at the gate is still sealed, and the appeal line says its driver was taking a child home.",anchor={print="IrvingtonSpeedway"}},
{id="t0024-02",kind="written",pieces={"memo"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The infield stays closed",body="Keep the infield closed until the pesticide trial dries. The first heat remains on the board, so the groundskeeper has to refund a child's ticket from his own coffee jar.\n\nThe trial crew sprayed the grass at dawn and the infield still smelled sweet at noon. Our copy stayed on the kitchen table.\n\nWhen I returned, the window was closed and the board was blank. I kept the page because it was the only one with our address.",anchor={print="IrvingtonSpeedway"}},
-- T0027
{id="t0027-01",kind="set",pieces={"Tarp","BathTowel"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Folded tarp beside the spare mark",body="the folded tarp and bath towel are wedged beneath unused warning tape. footprints pass around the bundle rather than toward it.",anchor={map="BBurgStashMap2",mark=1}},
{id="t0027-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Before the beds dry",body="The caretaker says the grounds crew borrowed the kitchen sink for a rinse. Please keep the side room locked until the treated beds are dry; the folding chairs are still needed tomorrow.\n\nThe beds along the wall were sprayed that morning and the leaves already curl. I kept this page with the garden receipts, not the ordinary papers.",anchor={map="BBurgStashMap2",mark=1}},
-- T0028
{id="t0028-01",kind="set",pieces={"EmptyJar","Pencil","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The unfinished handoff",body="The empty jar still holds a green film. A pencilled note tells the grounds crew to rinse the sprayed greens twice before they go to the kitchen, and counts the crates that came back with the film still on them.",anchor={map="BBurgStashMap3",mark=1}},
{id="t0028-02",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="One page put aside",body="The repair ticket orders the front doors welded shut at the checkpoint, but the locksmith billed for cutting off the back lock. A guard stood at the gap and turned away every family with a child.\n\nThe order had no name on it, only a stamp. I kept the scrap because the same stamp followed us from the previous stop. The first entry was crossed out; I have not tried to improve it.",anchor={map="BBurgStashMap3",mark=1}},
-- T0029
{id="t0029-01",kind="set",pieces={"GardenHoe","Camera"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hoe beside the spare mark",body="four notches on the hoe match four marks on the camera; a fifth was sanded flat on both. both are tied with cut roadblock tape, and the camera's frame counter stops at a checkpoint.",anchor={map="BBurgStashMap4",mark=1}},
{id="t0029-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="A corner still legible",body="I marked the water barrel too, after the field crew sprayed the rows upwind. They call the rinse routine; I still will not let the dog drink until the tank is flushed.\n\nThe barrel water had a green skin on it by morning and the beans nearest the spray went limp. I wrote the time before I went back for the others.",anchor={map="BBurgStashMap4",mark=1}},
-- T0030
{id="t0030-01",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The unfinished handoff",body="Do not sell the catch until the county finishes its water check. They called it routine, but the fish order is still in the icebox and the supplier wants payment.\n\nThe pond below the sprayed field had gone cloudy and the fish were up at the surface. I meant to ask about the runoff in the morning, but the farm crew had already left, and this was all that remained.",anchor={map="BBurgStashMap5",mark=1}},
{id="t0030-02",kind="set",pieces={"EmptySandbag","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Empty sandbag with the second seal",body="a scraped warning stripe marks the empty sandbag; a quarantine seal is stuck over the water bottle's cap. both are tied with the same cord.",anchor={map="BBurgStashMap5",mark=1}},
-- T0031
{id="t0031-01",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="The unfinished handoff",body="I left the spare key where you asked. The bus went past the property, but the office says our address was never on its pickup list. I thought you would come back for me.\n\nMy mother put it with the household bills so it would not be thrown away. It was the only part of the week that still had a date.\n\nSomeone had to finish the household list even though the office had closed. I wrote the names in the space left for expenses.",anchor={map="BBurgStashMap6",mark=1}},
{id="t0031-02",kind="set",pieces={"Notebook","Pencil","Teacup"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Ink through the paper",body="Two cups are set beside a test-day notebook of spray-plot rows. Both cups hold a sweet-smelling residue; the only signed line is for the room key, and a note asks that the sample page stay out of the household drawer.",anchor={map="BBurgStashMap6",mark=1}},
-- T0032
{id="t0032-01",kind="set",pieces={"DishCloth","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Dish cloth with the unclosed tally",body="the dish cloth and folded road map are tied with cut warning tape. six tally cuts mark the dish cloth; only four are crossed through.",anchor={map="BBurgStashMap7",mark=1}},
{id="t0032-02",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The drawer copy survived",body="Leave the canisters outside the fence until the grounds crew finishes the spray test. The gate was already locked when the delivery arrived; the return form charges us for the missing seal.\n\nThe grass along the fence went brown in stripes by the next day. Every canister carried a trial label, and the crew had no one left to ask.",anchor={map="BBurgStashMap7",mark=1}},
-- T0033
{id="t0033-01",kind="set",pieces={"PaperclipBox","WalkieTalkie1"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Paperclip box beside the spare mark",body="opposite route arrows are painted on the paperclip box and hand radio. the older arrow was scraped away beneath fresh road grit.",anchor={map="BBurgStashMap8",mark=1}},
{id="t0033-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="One page put aside",body="The room smells like the liquid from the field bottles, and Mom's throat still hurts. I opened the window; the return truck says nothing spilled.\n\nThe seedlings by the shed curled up after the spray run, and the barn cat won't go near the bottles. I put this page with the feed receipts.",anchor={map="BBurgStashMap8",mark=1}},
-- T0034
{id="t0034-01",kind="set",pieces={"Screwdriver","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Tool return",body="The factory tool sheet lists the sprayer nozzle as returned before the shift began; a grease thumbprint covers the signature.",anchor={map="EkronStashMap1",mark=1}},
-- T0035
{id="t0035-01",kind="set",pieces={"Potato","Notebook"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="The last crate",body="The potato crate has a delivery tag stamped by a checkpoint after the road was sealed. A pencilled note lists a turned-back driver and no destination.",anchor={map="EkronStashMap2",mark=1}},
-- T0036
{id="t0036-01",kind="set",pieces={"Bag_ALICEpack","Fertilizer"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Goods kept apart",body="A fertilizer bag is tied shut inside a supply pack, its seams dusted yellow-green; the page tucked under it lists spray-plot rows and a delivery to a field with no recipient.",anchor={map="EkronStashMap3",mark=1}},
-- T0037
{id="t0037-01",kind="set",pieces={"Stapler","FirstAidKit"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Stapler beside the spare mark",body="the stapler and first-aid kit were sealed together but never opened. soot darkens the bundle; clean outlines show it was packed before the fire.",anchor={map="EkronStashMap4",mark=1}},
-- T0038
{id="t0038-01",kind="set",pieces={"Bandage","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Aid for the school",body="The school aid list pairs a bandage with a note about the seed-treatment plot behind the school: a rash on the children's arms after the rows were sprayed. The last line asks who will collect the used kit.",anchor={map="EkronStashMap5",mark=1}},
-- T0039
{id="t0039-01",kind="set",pieces={"Bleach","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Advice by the sink",body="A bottle of bleach sits beside a copied warning and a water bottle with its cap still sealed. The note says the caller was told to wait for instructions.",anchor={map="EkronStashMap6",mark=1}},
-- T0040
{id="t0040-01",kind="set",pieces={"Map","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="A route left open",body="The marked route runs along the edge of the sprayed fields, with a pencilled return arrow and no destination name; a note beside it asks whether the field check on the wilted rows is still happening.",anchor={map="EkronStashMap7",mark=1}},
-- T0041
{id="t0041-01",kind="set",pieces={"HolePuncher","Clipboard"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hole punch beside the spare mark",body="matching white stripes cross the hole punch and clipboard. a name-sized patch on the hole punch has been scrubbed bare.",anchor={map="IrvingtonStashMap2",mark=1}},
-- T0042
{id="t0042-01",kind="set",pieces={"WalkieTalkie1","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Radio at the school",body="The school route slip tells the driver to radio before turning back; its attendance copy lists the field crew under “visitors.”",anchor={map="IrvingtonStashMap3",mark=1}},
-- T0043
{id="t0043-01",kind="set",pieces={"SheetPaper2","Pencil"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="A verse on the return",body="A copied verse about helping a wounded stranger is folded around an unpaid bar tab; the return slip marks the road pass as revoked.",anchor={map="IrvingtonStashMap4",mark=1}},
-- T0044
{id="t0044-01",kind="set",pieces={"Eraser","HandTorch"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Eraser dusted with field residue",body="the eraser and hand torch are both dusted with sweet yellow-green field residue, thick under the torch's grip and rubbed into the eraser's edge.",anchor={map="IrvingtonStashMap5",mark=1}},
-- T0045
{id="t0045-01",kind="set",pieces={"HandTorch","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Light for the careful",body="The torch is set on a marked route beside a note to check each door before leaving. The last checked address has no time beside it.",anchor={map="IrvingtonStashMap6",mark=1}},
-- T0046
{id="t0046-01",kind="set",pieces={"Notebook","SeedBag"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Field notes without a heading",body="A seed packet rests in a notebook whose first page is missing; the only surviving line asks whether the plots were watered before the crew arrived.",anchor={map="IrvingtonStashMap7",mark=1}},
-- T0047
{id="t0047-01",kind="set",pieces={"Pen","BathTowel"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Black pen beside the spare mark",body="red and blue cord join the black pen to the bath towel. the red route is cut; the blue route ends in a sealed knot.",anchor={map="IrvingtonStashMap8",mark=1}},
-- T0048
{id="t0048-01",kind="set",pieces={"Hammer","Nails"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Fortification order",body="A hammer and unopened nails sit beside a note to brace the garden-side door before the next treatment. The note does not say who will return.",anchor={map="IrvingtonStashMap9",mark=1}},
{id="t0048-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Fortify before the treatment",body="Farm log: “fortify here” meant boards over the garden door before the next treatment truck. The crew promised to collect its sample jars and never returned.\n\nMy mother put it with the household bills so it would not be thrown away. It was the only part of the week that still had a date.",anchor={map="IrvingtonStashMap9",note=1}},
{id="t0048-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="First heart, clean cot",body="Diary margin: the first heart marks the cot where the orchard crew slept after the spray run. Their boots left a sweet yellow dust; the family returned before anyone posted a warning.\n\nI wrote it down at the time, before the dust was swept. The cot's blanket still smelled sweet a week later.",anchor={map="IrvingtonStashMap9",note=2}},
{id="t0048-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Second heart, rinsed blanket",body="On the photograph back: second heart, our spare blanket. I rinsed green flecks from it after the seed-treatment men left, then the well began tasting of pennies.\n\nI kept the corner of the old page in my pocket. The flecks came out of the blanket slowly, and the well water was cloudy for days.",anchor={map="IrvingtonStashMap9",note=3}},
{id="t0048-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Third heart, borrowed room",body="Torn notebook page: the third heart is the room lent to two pasture-test workers. One wrote that the calves refused water after the pasture was sprayed.\n\nTheir boots by the door were caked with the same pale dust as the pasture gate. I wrote this down before their truck left.",anchor={map="IrvingtonStashMap9",note=4}},
{id="t0048-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Fourth heart, sealed window",body="Personal note: at the fourth heart we shut the window during the field misting. The kitchen herbs curled by supper, hours before the road patrol appeared.\n\nI set it aside to show the neighbor when she returned. Her porch was empty by the time the light was good enough to read it.\n\nThere may be a simple reason for the change. Nobody at the next stop could tell us what to do with the first version.",anchor={map="IrvingtonStashMap9",note=5}},
{id="t0048-07",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Fifth heart, empty cradle",body="Letter draft: the fifth heart was for the baby room. A crop-trial driver warned us not to use the rain barrel, but would not put his warning on the delivery slip.\n\nThe barrel had a rainbow sheen after the crop spray drifted over the roof. I wrote the date here while I could still remember it.",anchor={map="IrvingtonStashMap9",note=6}},
-- T0049
{id="t0049-01",kind="set",pieces={"RedPen","Camera"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Red pen beside the spare mark",body="chalk numbers run across the red pen and camera. the count skips one place, then resumes in a different hand.",anchor={map="IrvingtonStashMap10",mark=1}},
-- T0050
{id="t0050-01",kind="set",pieces={"Book","LetterHandwritten"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="A gift for the visit",body="A book is wrapped in a note asking someone to bring it on a family visit; the back lists the spray dates for the bean rows beside the garden hose, with a warning to keep the hose off the marked ground.",anchor={map="LouisvilleStashMap2",mark=1}},
-- T0051
{id="t0051-01",kind="set",pieces={"Screwdriver","Notebook"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Tools left at school",body="The janitor’s tool list marks the rear door repaired, but the key return is dated before the repair was finished.",anchor={map="LouisvilleStashMap3",mark=1}},
-- T0052
{id="t0052-01",kind="set",pieces={"Sledgehammer","PetrolCan"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The stop at the station",body="A sledge is marked for a station delivery while the fuel can is logged as empty before the driver’s return. The receipt leaves the destination blank.",anchor={map="LouisvilleStashMap4",mark=1}},
-- T0053
{id="t0053-01",kind="set",pieces={"Bag_Schoolbag","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="A family moved on",body="A school bag and water bottle are listed for collection at the gym, but the driver marked the family transferred before the pickup time.",anchor={map="LouisvilleStashMap5",mark=1}},
-- T0054
{id="t0054-01",kind="set",pieces={"SeedBag","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Home plot notes",body="A seed bag is stored beside a water bottle labelled for the back plot; a note says to stop watering until the test results arrive.",anchor={map="LouisvilleStashMap6",mark=1}},
-- T0055
{id="t0055-01",kind="set",pieces={"BluePen","Briefcase"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Blue pen beside the spare mark",body="the blue pen and briefcase are wrapped in a child's raincoat. one stayed dry while the other was left in road mud.",anchor={map="LouisvilleStashMap7",mark=1}},
-- T0056
{id="t0056-01",kind="set",pieces={"Pills","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Third door supply",body="A packet of pills is paired with a note to keep the third room ventilated after the field bottles are opened; the bottles' sweet smell gave the household headaches. The return line for the bottles is blank.",anchor={map="LouisvilleStashMap8",mark=1}},
-- T0057
{id="t0057-01",kind="set",pieces={"HuntingRifle","CannedCorn"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Stable stores",body="A food tin is tied to a stable key with a route note warning the next driver not to take the tree road. The return time is crossed out.",anchor={map="LouisvilleStashMap9",mark=1}},
-- T0058
{id="t0058-01",kind="set",pieces={"Bread","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Food from the sprayed rows",body="A bread receipt is tucked inside a note. The back lists garden rows sprayed on a given day and a delivery of produce from them that never reached the house.",anchor={map="LouisvilleStashMap10",mark=1}},
-- T0059
{id="t0059-01",kind="set",pieces={"MagnifyingGlass","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Magnifying glass beside the spare mark",body="a broken barrier board crushed the magnifying glass against the folded road map. clean undersides show both were there before the road was blocked.",anchor={map="LouisvilleStashMap11",mark=1}},
-- T0060
{id="t0060-01",kind="set",pieces={"Pizza","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Food tent supply",body="The tent's drink list includes water from the garden hose; a note says the hose was used to rinse spray tanks before the food shift, and the rinse water ran green into the bucket.",anchor={map="LouisvilleStashMap12",mark=1}},
