-- T0428
{id="t0428-01",kind="set",pieces={"SeedBag","Fertilizer"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The dry half of the sack",body="This seam has two colors of dust. The fertilizer reached the lower half; the dry seed at the top still comes away clean."},
{id="t0428-02",kind="set",pieces={"HandShovel","Bucket"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The sprayed shovel",body="The soil on this shovel stops at a sharp pale band. Above it the blade is crusted with spray residue and field grit; the bucket beside it holds stunted seedlings."},
{id="t0428-03",kind="set",pieces={"CornSeed","Twine"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The second planting",body="These seeds are separated with twine into two little piles. The damp ones have black tips; the dry ones have begun to sprout."},
{id="t0428-04",kind="set",pieces={"SeedBag","Rope"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The empty return",body="This folded bag has loose feed at the bottom and a tied-off strip from another bag. The strip is marked for a different delivery day."},
{id="t0428-05",kind="set",pieces={"EmptyJar","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The patch beneath the lid",body="There is a sticky green rim inside the jar and clean water in the bottle beside it. Only the jar's contents have gone cloudy."},
{id="t0428-06",kind="set",pieces={"SeedBag","CompostBag"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The bottom of the stack",body="The lowest sack has sprouted through its stitches. The bag above it is dry and still sealed."},
{id="t0428-07",kind="set",pieces={"Gloves_Dish","CarrotSeed"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The hand at the fence",body="A garden glove is folded around a seed packet; the fingertips have a dark crust that the packet's paper doesn't have."},
{id="t0428-08",kind="set",pieces={"Tarp","HandShovel"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The covered seedlings",body="The tarp's underside is dotted with pale leaves. Outside its edge the same size stems have gone dark at their tips."},
{id="t0428-09",kind="set",pieces={"CornSeed","Pot"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The spared row",body="This packet is unopened, tucked into a pot of healthy starts. A matching empty packet is stuck to the soil of the wilted tray."},
{id="t0428-10",kind="set",pieces={"Bowl","Fork","SeedBag"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The first return from the field",body="There is fresh soil in the lunch bowl and none on the fork. Someone set food down to carry a wet seed bag back in."},
-- T0429
{id="t0429-01",kind="set",pieces={"Bucket","Bowl"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The shared trough",body="The bucket has a white tide mark above a green one. The little bowl filled from it has the green line too."},
{id="t0429-02",kind="set",pieces={"WaterBottle","Twine"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The upstream bottle",body="Two bottles are tied to opposite ends of this cord. The one marked upstream is clear; the other holds a green sediment."},
{id="t0429-03",kind="set",pieces={"Kettle","Bucket","Tarp"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The dry tap",body="The kettle holds clean water. The bucket beside it is stained green where it caught the first rain running off the spray tarp, and the seedlings in the bucket are wilted."},
{id="t0429-04",kind="set",pieces={"Bowl","Bucket","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The dog that refused",body="The untouched bowl has the same green ring as the sprayer can. The overturned water bottle near it is clear. A wilted seedling lies across the bucket rim."},
{id="t0429-05",kind="set",pieces={"FishingNet","Bucket"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The lower ditch",body="A net catches grass and pale granules where the runoff narrowed. There are none in the dry mud above the waterline."},
{id="t0429-06",kind="set",pieces={"EmptyJar","JarLid"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The two jars",body="One jar is filled with rainwater and sealed. The other has flakes from a trough stuck inside the lid; only that one smells sour."},
{id="t0429-07",kind="set",pieces={"RubberHose","Wrench","Fertilizer"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The moved hose",body="The old hose end is brown with well water. A newer clamp is green inside, beside an empty sack of field additive."},
{id="t0429-08",kind="set",pieces={"Bucket","Spoon"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The settled bucket",body="The spoon comes up green from the bottom of the bucket. At the surface the water looks clear enough to drink."},
{id="t0429-09",kind="set",pieces={"Shoes_WorkBoots","Bucket"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The washed boots",body="One boot has spray residue caked in its tread; a bucket of gray rinse water stands beside them, and the seedlings in the bucket have yellowed. The mate sits clean and dry."},
{id="t0429-10",kind="set",pieces={"Wrench","Bucket"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The closed valve",body="The wrench has fresh scrape marks, and the bucket beyond the pipe is clear. The bucket on the field side still holds a green rim."},
-- T0430
{id="t0430-01",kind="set",pieces={"SeedBag","Rope"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The feed left untouched",body="A tied sack is full of pale pellets. The opened sack beside it has dark pellets and a chewed edge where something fed."},
{id="t0430-02",kind="set",pieces={"Milk","Spoon"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The milk before morning",body="The bottle of milk is curdled, though the sealed carton stayed cold beside it. A feed scoop is crusted at one end."},
{id="t0430-03",kind="set",pieces={"Egg","CornSeed"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The coop threshold",body="Eggshells from the inside nest are clean. The ones near the spilled feed have flecks of the same green grit."},
{id="t0430-04",kind="set",pieces={"Bucket","Wire"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The unused pail",body="The clean bucket is hung above reach; the one on the ground has hoof marks in its rim and residue at the bottom."},
{id="t0430-05",kind="set",pieces={"FishingNet","SeedBag"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The bird feeder",body="Seed caught in the mesh has gone gray. The spare packet beneath it is dry and yellow."},
{id="t0430-06",kind="set",pieces={"Rope","Bowl"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The pen rope",body="One end is polished by an animal's neck, the other stiff with dark feed dust. A small feed bowl is still tied beside it."},
{id="t0430-07",kind="set",pieces={"Apple","Corn"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The untouched crate",body="Two apples are bruised but clean. The corn in the same crate has a powder along its seam that was not there on the fruit."},
{id="t0430-08",kind="set",pieces={"Broom","SeedBag"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The barn sweep",body="The broom has dark grain caught in its bristles. The swept pile was bagged separately from the clean straw."},
{id="t0430-09",kind="set",pieces={"Spoon","Twine","Corn"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The borrowed scoop",body="A spoon holds pale feed beneath darker grains. Its handle is wrapped with twine as if someone meant to find it again."},
{id="t0430-10",kind="set",pieces={"Bowl","Rope","CornSeed"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The feed by the gate",body="The water bowl on this side is clean. Feed scattered across the hinge has the same dark flecks as the animal's collar, and the seed corn spilled with it has gone grey."},
-- T0431
{id="t0431-01",kind="set",pieces={"TirePump","Tarp"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The wheel's other field",body="Green dust sits in the tire pump's nozzle. The tarp wrapped around it is streaked where a wheel crossed from one field to another."},
{id="t0431-02",kind="set",pieces={"Shovel","Bucket"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The spare shovel",body="This shovel carries two soils: red clay under a fresh layer of pale spray dust. The bucket holds only the pale dust and a few yellowed seedlings."},
{id="t0431-03",kind="set",pieces={"Shovel","Fertilizer"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The borrowed ladder",body="The bottom rung is crusted with fertilizer. The clean top rung still has flakes from a different barn's paint."},
{id="t0431-04",kind="set",pieces={"DuctTape","RubberHose","WaterBottle"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The patched spray hose",body="The duct tape holds a split spray hose together. Its inner edge is green; the water bottle beneath the patch is flecked the same way."},
{id="t0431-05",kind="set",pieces={"Tarp","Rope"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The return tarp",body="One corner was folded inward while still wet. Under the crease the field grit is green with dried spray, and a withered crop seedling is pressed in the fold."},
{id="t0431-06",kind="set",pieces={"SeedBag","Tarp"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The load under the seat",body="The seed bag is torn across the bottom. The loose grain in the floor mat has the same black dust as the tear."},
{id="t0431-07",kind="set",pieces={"Broom","Twine"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The tied broom",body="Someone tied this broom to the outside of a load. Its bristles hold straw from one pen and dark treated-seed pellets from the field; a few scorched crop leaves are caught in the twine."},
{id="t0431-08",kind="set",pieces={"RubberHose","Bucket"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The washed wheel",body="The spray hose is coiled around the wheel; the rinse from it has pooled green in the bucket. A sprig of blackened crop leaves floats on top, and the other wheel stayed dry."},
{id="t0431-09",kind="set",pieces={"Rope","SeedBag"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The handoff rope",body="A knot still carries pale dust, but the free end has a dark crust. This rope has been tied around more than one load."},
{id="t0431-10",kind="set",pieces={"HandShovel","WaterBottle"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The clean blade",body="The spade blade was rinsed, leaving a strip of green soil in the socket where the water could not reach."},
-- T0432
{id="t0432-01",kind="set",pieces={"Bread","WaterBottle","Tissue"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The field lunch",body="The sandwich is untouched, but the cup is half empty and its lip is coated with spray dust from the field. A handkerchief beneath it has dried brown flecks, and a withered corn leaf is folded in it."},
{id="t0432-02",kind="set",pieces={"Shoes_WorkBoots","Newspaper"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The unworn pair",body="One work boot has damp field clay in its seams. Its mate is still packed with clean newspaper, as if its owner went out in one borrowed boot."},
{id="t0432-03",kind="set",pieces={"RippedSheets","Fertilizer"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The first cough at dawn",body="There are fresh drops on this cloth over a smear of fertilizer dust. The dry cloth tied beside it has none."},
{id="t0432-04",kind="set",pieces={"Bowl","Bread"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The supper carried home",body="A lunch bowl has grain husks stuck to its rim. The unopened bread beside it was packed for the same shift."},
{id="t0432-05",kind="set",pieces={"Jacket_ArmyCamoGreen","WaterBottle"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The borrowed coat",body="Dark treated-feed dust covers the outer sleeve of this jacket. The clean inside is pressed around a bottle with the same residue at its neck, and a scorched crop leaf is tucked in a pocket."},
{id="t0432-06",kind="set",pieces={"WaterBottle","RippedSheets"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The offered water",body="A full bottle is knotted to a strip of cloth already marked with brown spit. The second bottle has not been opened. A scorched leaf of seed corn lies beside them."},
{id="t0432-07",kind="set",pieces={"HandShovel","Bandage"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The shift's last tool",body="The hand shovel has fresh field soil and a cloth wrapped tightly around its grip, stained green from the sprayer. A bandage has been laid out but never used."},
{id="t0432-08",kind="set",pieces={"Purse","Spoon"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The feed clerk's pocket",body="A pinch of dark pellets has collected in the crease of this purse. The spoon beside it is bent from opening a feed sack."},
{id="t0432-09",kind="set",pieces={"Jacket_ArmyOliveDrab","Tissue"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The grass on the cuff",body="The cuff is crusted with pale spray granules and crushed crop leaves. A clean tissue in the pocket was never taken out."},
{id="t0432-10",kind="set",pieces={"Soap2","Gloves_Dish","WaterBottle"},where={{place="mapNamed",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},title="The unfinished washing",body="Soap is wet on one side and grain grit is still pressed into the glove fingers. The water bottle is nearly empty."},
-- T0433
{id="t0433-01",kind="set",pieces={"SeedBag","Newspaper"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The parcel under the letters",body="A seed packet leaked into this mailbox. The paper at the bottom is gritty, while the letters above it stayed clean."},
{id="t0433-02",kind="set",pieces={"CornSeed","SeedBag"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The returned packet",body="The opened packet is bound with a rubber band. A few dark kernels remain; a second unopened packet is tucked behind it."},
{id="t0433-03",kind="set",pieces={"SeedBag","Spoon"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The porch delivery",body="A sack strip and a feed scoop were pushed in here together. The scoop still carries the same dark grains stuck to the strip."},
{id="t0433-04",kind="set",pieces={"CarrotSeed","CornSeed"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The garden club exchange",body="These seeds came back with blackened tips. The packet mailed out beside them is still sealed."},
{id="t0433-05",kind="set",pieces={"Map","Twine","Corn"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The wrong doorstep",body="A bundle of grain is tied to a map with two pencil circles, one crossed out. The twine is damp with field mud."},
{id="t0433-06",kind="set",pieces={"EmptyJar","CarrotSeed"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The sample in a jar",body="A little jar holds green sediment and a dry seed packet has been folded over its lid. The parcel was too thick for the slot."},
{id="t0433-07",kind="set",pieces={"Newspaper","Tomato"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The quiet subscription",body="A newspaper is wrapped around a withered tomato vine. Its leaves are freckled where field dust collected."},
{id="t0433-08",kind="set",pieces={"DuctTape","SeedBag"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The spare label",body="A scrap of duct tape sticks to a sack corner. Two hand drawn arrows show where it was meant to go next."},
{id="t0433-09",kind="set",pieces={"SeedBag","Rope"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The closed loop",body="A sealed sack has been tied to a torn corner from an open sack. Their stitching matches, but only the open one has black dust."},
{id="t0433-10",kind="set",pieces={"CornSeed","EmptyJar"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The requested replacement",body="One packet of corn is damp and swollen; another was packed dry beside it. Someone left both here for collection."},
-- T0434
{id="t0434-01",kind="set",pieces={"Tarp","Cabbage"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The untouched patch",body="Under this tarp the leaves are still firm. Beyond its edge, the same plants are speckled along the side facing the field."},
{id="t0434-02",kind="set",pieces={"EmptyJar","HandShovel"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The two soils",body="The left jar holds brown soil from a dry bed. The right is gray and has root threads that broke at the slightest touch."},
{id="t0434-03",kind="set",pieces={"SeedBag","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The late bed",body="One seed packet is marked for a later sowing. Those plants are still green; the earlier plants beside them have collapsed."},
{id="t0434-04",kind="set",pieces={"Newspaper","Potato"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The sheltered tray",body="Roots wrapped in newspaper are white. Roots from the exposed bed are dark where the field spray settled."},
{id="t0434-05",kind="set",pieces={"Bucket","Tarp"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The different rain",body="Two buckets were left out, one under the roof and one beyond it. Only the open one has a powder ring from the field spray after the rain, and the seedling in it has wilted."},
{id="t0434-06",kind="set",pieces={"Twine","Fertilizer"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The fenced edge",body="Twine on this side of the fence is clean. The strand facing the tilled field carries tiny pale granules."},
{id="t0434-07",kind="set",pieces={"Potato","SeedBag"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The spared tubers",body="Potatoes from under the shed are firm. The ones from the near bed have soft spots beneath a film of field dust."},
{id="t0434-08",kind="set",pieces={"RippedSheets","Rope"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The cloth on the line",body="The clean cloth was hung indoors. The cloth from the outside line catches green spray grit in its weave, and a crop seedling pinned in the fold has yellowed."},
{id="t0434-09",kind="set",pieces={"Kettle","Bowl","HandShovel"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The covered water",body="This kettle's water is clear. A dish left in the yard has the same pale flecks as the soil in the shovel."},
{id="t0434-10",kind="set",pieces={"HandShovel","CarrotSeed"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The dry side of the furrow",body="The hand shovel is brown on one edge and gray on the other. The gray soil holds dead seedlings; the brown side has live roots."},
-- T0435
{id="t0435-01",kind="set",pieces={"Map","SeedBag","Pencil"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The last feed run",body="The vehicle map has pencil ticks at three stops. Grain caught in its fold matches the dark grain in the half empty bag."},
{id="t0435-02",kind="set",pieces={"Bucket","Soap2","Gloves_Dish"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The shared wash bucket",body="Soap floats in green wash water. Two different work gloves are jammed into the same bucket after a field shift."},
{id="t0435-03",kind="set",pieces={"Map","CarrotSeed"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The change of route",body="This map bends along a farm road. The opened packet in its crease leaked only after the route crosses the fields."},
{id="t0435-04",kind="set",pieces={"Tarp","SeedBag"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The clean truck bed",body="The tarp has a rectangle of untouched cloth where a crate stood. All around it lies the pale dust from the load."},
{id="t0435-05",kind="set",pieces={"Spoon","Newspaper"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The spare feed scoop",body="The spoon is wrapped in newspaper dated before the road closures. Dark feed dust has settled inside the fold."},
{id="t0435-06",kind="set",pieces={"Rope","SeedBag"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The split load",body="A knotted rope divides the bags. The sack on one side has a green dust mark; those on the other are clean."},
{id="t0435-07",kind="set",pieces={"WaterBottle","Map"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The leaking water can",body="A bottle has dripped across the map where farm roads meet. Its cap is stained green and the map dries with the same halo."},
{id="t0435-08",kind="set",pieces={"Shovel","Tarp"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The shifted field kit",body="The shovel's handle has two different colored clays. The tarp wrapped around it has fresh tears shaped by a narrow truck bed."},
{id="t0435-09",kind="set",pieces={"Pot","Fork"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The load carried home",body="A lunch pot is packed with feed dust instead of food. The clean fork inside it is still tied in paper."},
{id="t0435-10",kind="set",pieces={"TirePump","SeedBag"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The residue on the spare wheel",body="This tire pump is streaked with the same pale dust as the sack cord. The clean tool roll beside them stayed shut."},
-- T0436
{id="t0436-01",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The first sick calf",body="The calf stopped drinking after we opened the new feed. Its sister stayed in the back pen on the old sack and still pushed me for breakfast.\n\nI wrote that down before anyone thought to count people. The feed bill was due Friday. I kept telling myself the animal was sulking because I was late."},
{id="t0436-02",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Sunday at the water trough",body="We filled the near trough from the field line and the far one from the well. By dusk the near pen was quiet; the far pen made its usual racket.\n\nI switched the hose myself. My mother asked why I kept a note about water when the cattle needed hay."},
{id="t0436-03",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The hay stayed clean",body="The bale under the roof was sound. The loose hay left beside the sprayer curled at the edges, and the rabbits would only eat from the roofed bale.\n\nI had promised to sweep both piles before supper. Now the clean one is marked with my old blue string so I can find it in a hurry."},
{id="t0436-04",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The feed before the fever",body="My brother took the sacks to the poultry shed on Tuesday. He came back nauseated and slept through Wednesday's milking. The children who stayed in town were well that night.\n\nThe invoice sat under the sugar bowl because we still owed for the load. I was angry about the money before I was frightened about him."},
{id="t0436-05",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The open gate",body="Our goats grazed the ditch after the field truck passed. The ones shut in the upper pen ate the same hay but never reached the ditch, and they kept their appetites.\n\nI used to complain that the upper gate stuck. That day I was grateful and ashamed of how long it took me to notice why."},
{id="t0436-06",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The day the hens fell silent",body="Only the flock beside the new grain bin stopped laying. I gave the birds in the yard from the old tin; they made noise all morning and left eggs by noon.\n\nI put the feed scoop on a shelf rather than wash it. It seemed useful to know exactly which bin it had touched."},
{id="t0436-07",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The barn dust",body="I swept the packing room while the new seed bags were stacked there. By evening my throat burned. My cousin swept the empty stall next door and went to the dance.\n\nWe both laughed at my cough at first. I can still see the pale stripe the sacks left on the floor."},
{id="t0436-08",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The second watering",body="A row of beans wilted after water from the field barrel. The next row, planted the same day, had rainwater saved under the porch and still stood upright.\n\nI let the dry row grow long because I wanted to be sure I hadn't simply planted too late. Now both rows are easy to tell apart."},
{id="t0436-09",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The morning after the delivery",body="Three calves were off their feed in the pen that received the new grain. The others had the same weather and the same night watch but ate from an unopened older sack.\n\nI was supposed to balance the feed bill. Instead I drew the pen divisions on the back of the envelope."},
{id="t0436-10",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="What the river did not reach",body="The lower garden took the muddy overflow from the field. The upper garden stayed dry. A week later the lower leaves had black edges and the upper cabbage was still growing.\n\nI meant to take a photograph for the seed supplier. The camera was full of birthday pictures and I could not bring myself to use the last frame."},
-- T0437
{id="t0437-01",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The route on the feed bill",body="I counted three farms on the driver's usual loop. The first two took the pale sacks and each called about sick animals. The third refused the load because its storage room was full.\n\nHe was annoyed about bringing half his cargo home. I remember that because he made me sign for the return before he'd carry in my flour."},
{id="t0437-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The boots in the passenger seat",body="I drove the field worker to town after his boots split. He had come from the treated rows that morning. He shivered in my car while my sister, who had worked the covered greenhouse, complained only about the heat.\n\nWe bought a cheap pair of boots and left the old ones wrapped in newspaper. I never finished paying her back for the fuel."},
{id="t0437-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="Two stops past the mill",body="The first house took drinking water from a barrel beside the sprayed field. The next house had a covered well and said its children were eating normally.\n\nI carried the same groceries to both doors. The bread went stale at the first one because nobody wanted it."},
{id="t0437-04",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The load that crossed the bridge",body="The truck carried bagged seed on Monday, then produce on Tuesday without washing the bed. Green dust was still in the corners where the produce crates sat.\n\nI helped unload and found the dust on my cuffs. It was easier to make a joke about the driver's housekeeping than to ask him to turn around."},
{id="t0437-05",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The farmer who kept his old stock",body="One stop on my route turned back the replacement feed because there was no room for it. That man's animals were still feeding when the others stopped drinking.\n\nHis wife told me not to treat this as good luck. I wrote the dates on a grocery list in case I forgot which week the truck had gone through."},
{id="t0437-06",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The shared shovel",body="I lent our shovel across the fence after we dug the sprayed ditch by the bean rows. Their field had not been sprayed. They returned it with the same pale clay on its blade, and their beans where the dog dug have since gone yellow and curled.\n\nI meant to scrub it before the children used it in the garden. It stayed by the door."},
{id="t0437-07",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The wet market boxes",body="The boxes of greens came in with gritty water underneath. The dry boxes delivered an hour earlier stayed crisp; these left soft stems and the same green mark on my hands.\n\nI put them on separate shelves. The receipt printer was broken, so I wrote the difference on the back of my own shopping list."},
{id="t0437-08",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The trailer at dusk",body="The second farm borrowed the trailer after the feed run. No one rinsed the corners. Two days later they called about the young goats, though their own feed had not changed.\n\nI had wanted to lend them a clean blanket too, but there was only room for the trailer and a sack of bedding."},
{id="t0437-09",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The sacks under the canvas",body="Rain got through the canvas at the front of the load. The wet bags came apart; the dry bags at the back held their shape. The wet grain went out to the pens first.\n\nI put a mark on my pocket list so I'd remember which pen got which. It felt petty to count sacks while the animals refused breakfast."},
{id="t0437-10",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The worker on the return trip",body="I took the field crew home in two trips. The crew who sprayed the south rows looked tired before sundown. The crew who repaired the fence away from those rows argued about pay all the way back.\n\nThey shared a truck and the same sandwiches. I wrote their tasks down on the back of a fuel receipt because the faces were beginning to blur."},
-- T0438
{id="t0438-01",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The covered cistern",body="We caught the same rain in two places. The barrel by the fields stood open; the cistern beneath the roof stayed shut. Only the barrel grew a green ring and left the dog unwilling to drink.\n\nI promised to paint the cistern lid when the weather cleared. It seems absurd now that I was worried about the color."},
{id="t0438-02",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The first bucket from the ditch",body="Water from the low ditch left grit in our kitchen pail. The ditch runs along the sprayed oat field, and the well water was clear. My father drank the ditch water at work and spent the next morning unable to stand.\n\nI saved the grit in a little jar. The oats along the ditch have gone yellow in a strip."},
{id="t0438-03",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The rain after spraying",body="The sprayed field ran into the pond during the storm. The pond fish floated up the next morning, but the pond behind the hill still had them moving below the surface.\n\nMy nephew had planned to fish both ponds. I took away his net and told him we'd go when the water was clear."},
{id="t0438-04",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The hose switch",body="The gardener filled six watering cans from the field line, where the spray tank drains, and four from the house tap. Only the beds watered from the field line lost their new leaves.\n\nThe gardener says the cans were identical. I checked the roots because I wanted him to be wrong; they were brown and soft."},
{id="t0438-05",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The cup in the greenhouse",body="The greenhouse well was capped for repairs, so the workers used the open tank outside the trial rows. Three complained of a bitter taste before their afternoon break; the repair crew drank from a jug brought from home.\n\nI brought the jug myself. It stayed half full, and I kept wishing I had brought enough for everyone."},
{id="t0438-06",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The opposite bank",body="A thin layer of pale dust settled on the downstream bank after the fields were washed. The upstream bank had only the usual silt. The chickens pecked at the lower bank and would not eat supper.\n\nI had gone down there to collect smooth stones for my daughter. I left the stones and came back for the birds."},
{id="t0438-07",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The uncovered rain dish",body="I set out two dishes for the dog, one beneath the eaves and one beside the field gate. The gate dish gathered green specks overnight. The dog sniffed it and drank the covered one dry.\n\nThe gate dish was a wedding gift and I felt foolish testing rain in it. I washed it twice and the mark came back when it dried."},
{id="t0438-08",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The clay in the kettle",body="The family by the lower road asked me to boil their water. A green ring stuck inside the kettle. My own well water boiled in it before without leaving a mark.\n\nTheir youngest carried the kettle to my door because his mother was too weak. I put it on the stove before he had finished speaking."},
{id="t0438-09",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The neighbor's fish",body="The ditch by the seeded field held dead minnows in the shallows. The creek beyond the ridge still had live fish. My neighbor wanted to blame the heat, though both waters were under the same sun.\n\nWe had meant to take the children wading. I folded their towels away and kept the little sketch I made of the two channels."},
{id="t0438-10",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The closed reservoir",body="When the new field powder arrived, the water trough nearest the mixing shed developed a chalky edge. The closed reservoir at the far end did not. The animals pushed past one another to drink from the far one.\n\nI was asked to check the fences, so I did. I also wrote down where each trough was filled; that part was my own idea."},
-- T0439
{id="t0439-01",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The grain from the upper bin",body="I fed the hens from the upper bin on Monday. They laid as usual. Tuesday's scoop came from the lower bin after the delivery, and by Thursday they had stopped laying.\n\nI cleaned the nesting boxes twice before I thought about which grain I had used. The lower bin still smells sweet when opened."},
{id="t0439-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The stray animals",body="Two dogs found the spilled feed by the unloading ramp. The neighbor's dog stayed tied at home and kept asking for scraps at supper. The two strays lay under the ramp by morning.\n\nI took bowls down to them because I thought they were hungry. Their water was untouched; the feed pile was smaller."},
{id="t0439-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The sheep beyond the hedge",body="The sheep that pushed through the hedge grazed along the trial field. The ones that stayed behind ate the same winter hay. Only the wanderers went off their food.\n\nI mended the hedge with spare wire. It was a job I had postponed all spring because I thought the animals preferred our grass."},
{id="t0439-04",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The eggs at the back of the shed",body="The hens closest to the open feed sacks left thin shells. The birds behind the closed partition laid hard shells that cracked normally in my hands.\n\nI kept the eggs separate in two bowls. My daughter was annoyed because she thought I was sorting them by size for a cake."},
{id="t0439-05",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The sack marked for the pigs",body="A new sack reached the pigs before the horses. The pigs lost their appetite first; the horses were still eating the old grain from the blue barrel.\n\nI put the empty sack under a stone. I had paid for both loads and did not want a dispute over which delivery came first."},
{id="t0439-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The pasture beside the ditch",body="The cows grazed the strip beside the field ditch after a night of rain. The high pasture remained dry, and the young heifers there kept feeding.\n\nI drew the gate on this page so my brother would not open it by habit. He used to say I worried more about gates than cattle."},
{id="t0439-07",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The seed on the windowsill",body="I sprouted two handfuls from different bags in jars by the same window. The older grain opened. The new grain made a film on the glass and did not grow.\n\nI wanted to prove the supplier had sent dead seed, which seemed an ordinary nuisance. The smell that followed was new to me."},
{id="t0439-08",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The cat at the mill",body="The mill cat ate spilled grain from the fresh shipment and stopped hunting. The other cat slept upstairs where the old stores were, and still stole my lunch.\n\nI had scolded the first cat for leaving a mouse at my feet. The next day it did not come when I shook the tin."},
{id="t0439-09",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The separated feed pans",body="We filled one pan from the new bag and one from the sack left over from winter. The chickens chose both without hesitation. By evening the ones from the new pan stood still in the corner.\n\nMy father asked me to take away both pans. I kept the grain apart, though it meant washing another dish."},
{id="t0439-10",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The ducks and the dry yard",body="The ducks went into the field pond while the chickens stayed in the dry yard. By supper the ducks drifted at the bank. The chickens still fought over the scraps.\n\nI had never seen the ducks ignore bread. I left it where it fell and went inside for the net."},
-- T0440
{id="t0440-01",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The scraped pump handle",body="I worked the irrigation pump after the trial mix spilled near its intake. The handle left a pale smear on my hand. The other worker who stayed at the dry well never touched the pump and ate supper.\n\nMy palms began to itch before we heard about any illness in town. I had intended to borrow his gloves the following day."},
{id="t0440-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The green seam in the truck",body="The feed truck dropped its first load at our farm. We swept the bed but the seam still held green grit when it collected another family's produce. They called two days later about a strange taste.\n\nI had swept that seam myself. I went back with a stiff brush and could still lift a pinch of the same grit."},
{id="t0440-03",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The sacks at the crossing",body="The truck driver tied the wet sacks on the outside of the load to dry. Seeds fell where the road crossed the creek, and the goats began to graze there.\n\nI found a torn strip of sack on the fence. My first thought was that somebody would expect me to pay for the lost grain."},
{id="t0440-04",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The field crew's wash",body="The crew washed their sprayers in the yard by the shared drain. The next morning our downspout bucket carried a green ring. The covered barrel beside the house did not.\n\nI used the bucket for mopping before I looked at the rim. The floor smelled like the field, so I took the mop outside."},
{id="t0440-05",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The apron on the line",body="My sister wore her work apron home from the seed sorting shed and hung it with the baby clothes. The apron shed pale dust when the wind picked up; the clothes farther down the line stayed clean.\n\nShe had planned to wash it in the morning. I took it down that night because it left grit on my fingers."},
{id="t0440-06",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The second plot with the same rake",body="We raked the treated plot, then used the rake on the garden behind the house. The first garden row the rake touched curled at the tips; the last row, planted later with a clean tool, stayed straight.\n\nI knew whose rake it was because the handle had my initials burned into it. I had not noticed what lodged between the teeth."},
{id="t0440-07",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="vehicle",lean="agricultural",rival="containment"}},title="The rented trailer",body="The first owner carried field bags in the trailer. The next carried hay to an untouched farm. Powder remained behind the hinges, and the animals fed from the hay before they showed any trouble.\n\nI wrote down who had the trailer on which day because we shared the hire fee. None of us was thinking about what had collected in the hinges."},
{id="t0440-08",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The wrong side of the gloves",body="I turned the field gloves inside out and carried them in my coat. The lining had dust from the mixing shed; my clean scarf picked it up before I got home.\n\nThe scarf was a gift. I nearly washed it with the rest of the laundry but could see where the dust had transferred."},
{id="t0440-09",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The borrowed bucket at the gate",body="They borrowed our bucket to rinse a field tank. When it came back, the inside had a faint green line. My son used it to water the beans; only that bed browned along its edges.\n\nI should have checked it before lending it to him. He wanted to help and had already filled it when I saw the mark."},
{id="t0440-10",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The flour in the mill",body="The grain sacks stood beside the mill's intake fan. Pale treated-seed powder from their seams got into the flour bags nearest the fan, and those bags show a grey cast; the bags stacked behind the far wall remained white.\n\nThe miller said we could exchange the nearest bags. I wrote their positions down because all the labels looked the same."},
-- T0441
{id="t0441-01",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The unopened batch",body="We had two packets of the same seed. The packet kept sealed in the kitchen sprouted in a damp cloth. The open packet used beside the treated field did not; its kernels stained the cloth gray.\n\nI left both cloths on the windowsill. My mother kept asking when I would clear the mess away."},
{id="t0441-02",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The hill garden",body="The lower beds received the runoff from the new fields. The hill beds got the same rain but no runoff. Only the lower leaves curled and only the family tending them complained of a bitter taste at the tap.\n\nI marked the beds in my own sketch because I had promised to bring them seedlings. I still had healthy ones from the hill."},
{id="t0441-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The old and new feed",body="We mixed half a sack from the new delivery with the old feed for one pen. Another pen stayed on the old feed alone. Both had the same keeper; only the mixed pen went quiet overnight.\n\nThe keeper was my uncle. He had insisted the new grain smelled better. I wrote down the scoops before we argued about memory."},
{id="t0441-04",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The unsprayed corner",body="The trial crew stopped their work where the fence collapsed. Plants behind the broken fence stayed green; those along the completed rows carried small white spots the next day.\n\nI repaired the fence with my neighbor. We left the corner open on purpose once we saw how different the rows looked."},
{id="t0441-05",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The covered produce",body="The crates under canvas went to one shop; the uncovered crates from the same field went to another. The uncovered leaves had a fine gritty edge and spoiled first.\n\nI bought a bunch from each shop so I could compare them in my kitchen. The shopkeepers both thought I was bargaining over pennies."},
{id="t0441-06",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The dry weather week",body="Nothing fell from the sky for six days. The upper field stayed sound while the trial plot wilted after its second application. The nearest laborers started missing meals before the rain came.\n\nI had written the dry days down because I hoped they would end. Now I keep turning back to that part of the calendar."},
{id="t0441-07",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The garden behind the wall",body="Both gardens shared a well. Only the beds beside the treated field received drifting dust; the wall sheltered the others. The exposed beans yellowed first.\n\nI thought the wall was stealing light from the sheltered beans. They grew taller anyway. My sister wanted to pull them up for supper."},
{id="t0441-08",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The returning birds",body="Birds kept pecking at the old grain spilled by the shed. They avoided the new spill from the sacks, even when the old pile was nearly gone.\n\nI swept neither pile because I wanted to see if they would change their minds. The owner complained that I was leaving a mess beside his door."},
{id="t0441-09",kind="written",pieces={"letter"},where={{place="mapNamed",spot="mailbox",lean="agricultural",rival="containment"}},title="The two harvest baskets",body="Both baskets held vegetables from the same planting. One came from the sprayed edge and softened by morning; the other, picked beyond the ditch, stayed crisp.\n\nI marked the handles with string. They were borrowed baskets and I knew I would have to return them even if I could no longer sell what was inside."},
{id="t0441-10",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="The farther trough",body="The near trough was topped up from the runoff ditch of the sprayed pasture and the far trough from a tank. The animals walked past the near trough without drinking; their keeper, who filled it, was already feverish, and the grass at the ditch edge is scorched.\n\nI made a sketch of the pipe before anyone moved the hose. I had offered to take his shift."},
}}
